/*
 * prog55_connected_components.c
 *
 * Re‑implementation of the original program whose behaviour was
 * observed in the supplied binary.  The program reads an undirected
 * graph from the command line (pairs of vertex numbers), checks the
 * input, builds an adjacency matrix for at most 8 vertices and then
 * prints the connected components.
 *
 * Output format (exactly as the original binary produces):
 *
 *     0: {0,1,2}
 *     1: {3}
 *     …
 *
 * If the command line does not contain an even number of arguments
 * after the program name, or any vertex number is outside the range
 * 0‑7, the program prints the single line "INVALID_INPUT" and exits
 * with status 1.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8                     /* maximum number of vertices */

int main(int argc, char **argv)
{
    /* The original binary expects an even number of arguments after the
       program name – each edge is given by a pair of vertex numbers.   */
    if ( (argc - 1) % 2 != 0 ) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* adjacency matrix, visited flag array and a simple queue for BFS */
    int adj[MAXV][MAXV] = {{0}};
    int visited[MAXV] = {0};
    int queue[MAXV];

    /* -----------------------------------------------------------------
       Parse the edge list.
       Each pair argv[i] argv[i+1] (i starts at 1) is an undirected edge.
       Vertices must be in the range [0,7]; otherwise the input is invalid.
       ----------------------------------------------------------------- */
    for (int i = 1; i < argc; i += 2) {
        long a = strtol(argv[i],     NULL, 10);
        long b = strtol(argv[i + 1], NULL, 10);

        if (a < 0 || a >= MAXV || b < 0 || b >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[a][b] = 1;
        adj[b][a] = 1;
    }

    /* -----------------------------------------------------------------
       Find and print the connected components.
       The components are discovered in increasing vertex order (0..7)
       using a breadth‑first search, exactly matching the behaviour of
       the original program.
       ----------------------------------------------------------------- */
    int component_id = 0;

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;                       /* already part of a component */

        /* BFS initialisation */
        int q_head = 0, q_tail = 0;
        queue[q_tail++] = start;
        visited[start] = 1;

        /* store the vertices of the current component */
        int comp_vertices[MAXV];
        int comp_size = 0;

        while (q_head < q_tail) {
            int v = queue[q_head++];
            comp_vertices[comp_size++] = v;

            for (int w = 0; w < MAXV; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = 1;
                    queue[q_tail++] = w;
                }
            }
        }

        /* ----- output the component ----- */
        printf("%d:", component_id);
        printf(" {");
        for (int i = 0; i < comp_size; ++i) {
            if (i > 0)
                putchar(',');
            printf("%d", comp_vertices[i]);
        }
        putchar('}');
        putchar('\n');

        ++component_id;
    }

    return 0;
}
